package com.bidx.util; import javax.crypto.SecretKeyFactory; import javax.crypto.spec.PBEKeySpec; import java.security.*; import java.util.*;
public final class PasswordUtil { private PasswordUtil(){} public static String hash(String password){try {byte[] salt=new byte[16];SecureRandom.getInstanceStrong().nextBytes(salt); byte[] out=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(password.toCharArray(),salt,120000,256)).getEncoded(); return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(out);}catch(Exception e){throw new IllegalStateException(e);}} public static boolean matches(String p,String saved){try {String[] a=saved.split(":");byte[] out=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(p.toCharArray(),Base64.getDecoder().decode(a[0]),120000,256)).getEncoded();return MessageDigest.isEqual(out,Base64.getDecoder().decode(a[1]));}catch(Exception e){return false;}} }
